<script setup lang="ts">
import { shallowRef } from 'vue'
import { checkSignedUpdate, fetchUpdateManifest } from '../services/lottolab'
const update = shallowRef('尚未检查'); const install = shallowRef<null | (() => Promise<void>)>(null)
async function checkUpdate(){ try { const signed=await checkSignedUpdate(); if(signed){ update.value=`发现已签名版本 ${signed.version}：${signed.notes ?? '请查看 Release 说明'}`; install.value=signed.install; return } const result=await fetchUpdateManifest();update.value=result?`发现发布版本 ${result.version}，当前构建未配置更新公钥。`:'暂无可读取的发布更新清单。' } catch { update.value='更新检查失败或当前开发构建未配置更新公钥。' } }
async function installUpdate(){ if(!install.value) return; update.value='正在下载并验证签名…'; await install.value(); update.value='更新已完成，应用将按系统提示重启。' }
</script>
<template><div class="view"><header><p class="eyebrow">LOCAL DATA & RESPONSIBILITY</p><h1>设置与关于</h1><p>数据、收藏和策略都保存在本机；LottoLab 不提供任何投注或售彩功能。</p></header><section class="grid"><article><h2>数据同步</h2><p>双色球与大乐透分别通过官方数据接口增量同步。同步失败时会继续使用本地缓存。</p><small>CSV格式：game, issue, draw_date, primary_numbers, secondary_numbers, sales_yuan, pool_yuan</small></article><article><h2>软件更新</h2><p>自动更新从 GitHub Release 获取签名清单。正式发布前需在仓库 Secrets 配置 Tauri 更新私钥。</p><div><button type="button" @click="checkUpdate">检查更新</button><button v-if="install" type="button" @click="installUpdate">下载并安装</button></div><small>{{ update }}</small></article><article><h2>责任提示</h2><p>历史评分不等于中奖概率。所有合法号码组合的理论中奖机会相同。</p><small>非官方产品，仅供统计研究；理性购彩，禁止未成年人购彩。</small></article><article><h2>版权说明</h2><p>LottoLab 源码公开于 LightyearXizIl/LottoLab，但保留全部权利，未授予开源许可证。</p><small>不使用任何福彩、体彩官方标识或服务。</small></article></section></div></template>
